#include "../tqs-cuda/kernel.cu"
#include "../tqs-cuda/host_task.cpp"
#include <vector>
#include <fstream>
#include <chrono>
#include <cstdio>
#include <cmath>
static void ck(cudaError_t x){if(x!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(x));exit(2);}}
std::vector<double> load(const char*f){std::ifstream in(f,std::ios::binary|std::ios::ate);if(!in)exit(3);size_t n=in.tellg();if(n%8)exit(3);in.seekg(0);std::vector<double>v(n/8);in.read((char*)v.data(),n);if(!in)exit(3);return v;}
template<class T>struct Buf{int n;std::vector<T>h;T*base,*d;Buf(int n,T guard):n(n),h(n+128,guard){ck(cudaMalloc(&base,h.size()*sizeof(T)));d=base+64;ck(cudaMemcpy(base,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}void read(){ck(cudaMemcpy(h.data(),base,h.size()*sizeof(T),cudaMemcpyDeviceToHost));}~Buf(){cudaFree(base);}};
struct Case{int T,B,Q,P,it;std::vector<task_t>pool,q;std::vector<int>data,dq;Buf<task_t>tasks;Buf<int>gpu,counter;Case(int t,int b,int qu,int p,int it):T(t),B(b),Q(qu),P(p),it(it),pool(p),q(qu),data(p*t),dq(qu*t),tasks(qu+b,task_t{16384,16384}),gpu(qu*t,16384),counter(1,16384){}};
void append(std::vector<double>&a,const std::vector<int>&b){for(int x:b)a.push_back(x);}void append(std::vector<double>&a,const std::vector<task_t>&b){for(auto x:b){a.push_back(x.id);a.push_back(x.op);}}
int main(){auto pre=load(FIXTURE),gold=load(ORACLE);size_t pos=1;std::vector<Case*>cs;for(int ci=0;ci<4;ci++){int T=pre[pos++],B=pre[pos++],Q=pre[pos++],P=pre[pos++],it=pre[pos++];auto c=new Case(T,B,Q,P,it);for(int i=0;i<P;i++)c->pool[i]={i,int(pre[pos++])};cs.push_back(c);}if(pos!=pre.size())return 3;
 auto run=[&](Case&c,std::vector<double>&art){std::vector<std::vector<int>>before(c.P/c.Q),after(c.P/c.Q),counts(c.P/c.Q);std::vector<std::vector<task_t>>tasks(c.P/c.Q);for(int k=0;k<c.P/c.Q;k++){before[k].resize(c.gpu.h.size());after[k].resize(c.gpu.h.size());counts[k].resize(c.counter.h.size());tasks[k].resize(c.tasks.h.size());}ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();std::fill(c.data.begin(),c.data.end(),0);int written=0,zero=0;
 for(int off=0,k=0;off<c.P;off+=c.Q,k++){host_insert_tasks(c.q.data(),c.dq.data(),c.pool.data(),c.data.data(),&written,c.Q,off,c.T);ck(cudaMemcpyAsync(c.tasks.d,c.q.data(),c.Q*sizeof(task_t),cudaMemcpyHostToDevice));ck(cudaMemcpyAsync(c.gpu.d,c.dq.data(),c.Q*c.T*sizeof(int),cudaMemcpyHostToDevice));ck(cudaMemcpyAsync(c.counter.d,&zero,4,cudaMemcpyHostToDevice));ck(cudaMemcpy(before[k].data(),c.gpu.base,c.gpu.h.size()*4,cudaMemcpyDeviceToHost));call_TaskQueue_gpu(c.B,c.T,c.tasks.d,c.gpu.d,c.counter.d,c.it,off,c.Q,12);ck(cudaGetLastError());ck(cudaMemcpy(c.data.data()+off*c.T,c.gpu.d,c.Q*c.T*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(after[k].data(),c.gpu.base,c.gpu.h.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(tasks[k].data(),c.tasks.base,c.tasks.h.size()*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(counts[k].data(),c.counter.base,c.counter.h.size()*4,cudaMemcpyDeviceToHost));}
 double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();for(int k=0;k<c.P/c.Q;k++){append(art,before[k]);append(art,after[k]);append(art,tasks[k]);append(art,counts[k]);}append(art,c.data);art.push_back(written);return t;};
 for(auto c:cs){std::vector<double>v;run(*c,v);}for(int trial=1;trial<=5;trial++){auto art=pre;std::vector<double>times;for(auto c:cs)times.push_back(run(*c,art));if(art.size()!=pre.size()+gold.size())return 5;bool ok=true;for(size_t i=0;i<gold.size();i++)ok&=art[pre.size()+i]==gold[i];std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)art.data(),art.size()*8);f.close();if(!f)return 6;double total=0;for(double x:times)total+=x;
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":null,\"timing_region\":\"sum4_source_CPUenqueue_H2D_persistentqueue_D2H_with_full_input_guard_observers\",\"jit_excluded\":true,\"internal_repeats\":1,\"native_reference_repaired\":true,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[%.17g,%.17g,%.17g,%.17g],\"authored_device_kernels\":1,\"original_kernel_body_unchanged\":true}\n",trial,total,ok?"true":"false",art.size(),path.c_str(),art.size(),times[0],times[1],times[2],times[3]);}for(auto c:cs)delete c;}
